def calc(expr: str) -> int | str:
    def trunc_div(a: int, b: int) -> int:
        # Toward-zero division; Python's // floors instead.
        if b == 0:
            raise ZeroDivisionError
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    prec = {"^": 4, "u-": 3, "*": 2, "/": 2, "%": 2, "+": 1, "-": 1}
    right_assoc = {"^", "u-"}
    output: list = []
    ops: list[str] = []
    expect_operand = True
    i = 0
    n = len(expr)

    def push_op(op: str) -> None:
        # A prefix minus starts the operand, so it must not reduce a pending '^'.
        if op != "u-":
            while ops and ops[-1] != "(":
                top = ops[-1]
                top_p = prec[top]
                op_p = prec[op]
                if top_p > op_p or (top_p == op_p and op not in right_assoc):
                    output.append(ops.pop())
                else:
                    break
        ops.append(op)

    while i < n:
        ch = expr[i]
        if ch == " ":
            i += 1
            continue
        if ch.isdigit():
            j = i + 1
            while j < n and expr[j].isdigit():
                j += 1
            output.append(int(expr[i:j]))
            i = j
            expect_operand = False
            continue
        if ch == "(":
            ops.append("(")
            i += 1
            expect_operand = True
            continue
        if ch == ")":
            while ops[-1] != "(":
                output.append(ops.pop())
            ops.pop()
            i += 1
            expect_operand = False
            continue
        if ch == "-" and expect_operand:
            push_op("u-")
            i += 1
            continue
        push_op(ch)
        i += 1
        expect_operand = True

    while ops:
        output.append(ops.pop())

    try:
        stack: list[int] = []
        for tok in output:
            if isinstance(tok, int):
                stack.append(tok)
                continue
            if tok == "u-":
                stack.append(-stack.pop())
                continue
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            elif tok == "/":
                stack.append(trunc_div(a, b))
            elif tok == "%":
                stack.append(a - b * trunc_div(a, b))
            else:
                if b < 0:
                    return "error"
                stack.append(pow(a, b))
        return stack[0]
    except ZeroDivisionError:
        return "error"
